// ---- shared limbs ---------------------------------------------------------------
function holdPre(ctx, P, hL, hR) { if (!P.hold) return; if (P.hold.L0) P.hold.L0(ctx, hL[0], hL[1]); if (P.hold.R0) P.hold.R0(ctx, hR[0], hR[1]); }
