function leg(ctx, hx, hy, fx, fy, r, fill, o = {}) { const p = capsule(hx, hy, fx, fy - r * .6, r, r * .9); fillShade(ctx, p, fill, { tex: o.tex, grain: .2 }); ink(ctx, p, 3); }
