  for (let i = 1; i <= 5; i++) { const x0 = lerp(c.br[0], c.bl[0], (i - 1) / 5), x1 = lerp(c.br[0], c.bl[0], i / 5); p.quadraticCurveTo((x0 + x1) / 2, c.br[1] + (i % 2 ? .045 : -.005), x1, c.bl[1]); }
