  ctx.globalAlpha = .9; ctx.setLineDash([.025, .018]); ctx.strokeStyle = '#c48f3c'; ctx.lineWidth = 2.2 * lw; ctx.beginPath(); ctx.moveTo(c.bl[0] + .07, -.02); ctx.lineTo(c.br[0] - .07, -.02); ctx.stroke(); ctx.setLineDash([]);
