  ctx.fillStyle = '#9aab52'; for (const s of [-1, 1]) { const l = new Path2D(); l.ellipse(.02 + s * .027, -.115, .028, .014, -s * .5, 0, 7); ctx.fill(l); ctx.stroke(l); }
